  "claim": {
    "component_id": "C040.component",
    "value": "Absent events cannot distinguish abandonment from offline preparation.",
    "scope": "A limitation of event absence alone; other evidence may distinguish these states.",
    "provenance": {
      "refs": [
        {
          "source_id": "P024",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span directly states the ambiguity between abandonment and offline preparation when events are absent."
    }
  },
  "signal_basis": {
    "component_id": "C040.signal_basis",
    "value": "An onboarding trajectory has no recorded milestone events or observed return to active product work.",
    "scope": "Absence of activity in the recorded events, considered alone.",
    "provenance": {
      "refs": [
        {
          "source_id": "P024",
          "role": "SUPPORT"
        },
        {
          "source_id": "P016",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans identify absent events and accounts with no return as observations within the mapping."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C040.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed to warrant this bounded limitation."
    }
  },
  "rationale": "Both abandonment and offline preparation can produce no recorded product activity. Event absence therefore cannot by itself discriminate between them, even when observation procedures are correctly executed.",
  "uncertainty": "An individual account's actual state remains unresolved by event absence alone.",
  "anomalies": []
